(function() {
    'use strict';

    class TestLabAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'TestLab: A/B Testing Lab';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    id: 'onboarding',
                    titleKey: 'r1_title',
                    bestMetric: 'conversion',
                    bestDecision: 'ship',
                    bestSample: '25000',
                    bestDuration: '4',
                    bestCorrection: 'bonferroni',
                    bestPeek: 'wait',
                    resultsKey: 'r1_results',
                    briefingKey: 'r1_briefing'
                },
                {
                    id: 'pricing',
                    titleKey: 'r2_title',
                    bestMetric: 'revenue',
                    bestDecision: 'segment',
                    bestSample: '25000',
                    bestDuration: '4',
                    bestCorrection: 'bonferroni',
                    bestPeek: 'wait',
                    resultsKey: 'r2_results',
                    briefingKey: 'r2_briefing'
                },
                {
                    id: 'feature',
                    titleKey: 'r3_title',
                    bestMetric: 'engagement',
                    bestDecision: 'followup',
                    bestSample: '50000',
                    bestDuration: '4',
                    bestCorrection: 'bonferroni',
                    bestPeek: 'wait',
                    resultsKey: 'r3_results',
                    briefingKey: 'r3_briefing'
                },
                {
                    id: 'retention',
                    titleKey: 'r4_title',
                    bestMetric: 'retention',
                    bestDecision: 'segment',
                    bestSample: '50000',
                    bestDuration: '4',
                    bestCorrection: 'fdr',
                    bestPeek: 'wait',
                    resultsKey: 'r4_results',
                    briefingKey: 'r4_briefing'
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    score: 0,
                    experimentsRun: 0,
                    correctDecisions: 0,
                    subscribers: 2000000,
                    scoreHistory: [],
                    decisionQualityHistory: [],
                    roundDetails: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    sampleSize: 50000,
                    duration: 4,
                    metric: 'conversion',
                    correction: 'bonferroni',
                    peek: 'wait',
                    decision: 'noship'
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var sampleEl = document.getElementById('sampleSizeInput');
            if (sampleEl) decisions.sampleSize = parseInt(sampleEl.value);

            var durationEl = document.getElementById('durationInput');
            if (durationEl) decisions.duration = parseInt(durationEl.value);

            var metricEl = document.getElementById('metricInput');
            if (metricEl) decisions.metric = metricEl.value;

            var correctionEl = document.getElementById('correctionInput');
            if (correctionEl) decisions.correction = correctionEl.value;

            var peekEl = document.getElementById('peekInput');
            if (peekEl) decisions.peek = peekEl.value;

            var decisionEl = document.getElementById('decisionInput');
            if (decisionEl) decisions.decision = decisionEl.value;

            if (!decisions.sampleSize || !decisions.duration || !decisions.metric || !decisions.decision) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('missing_warning'), 'warning'
                );
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];

            var designScore = 0;
            var decisionScore = 0;
            var maxDesign = 50;
            var maxDecision = 50;

            if (d.peek === 'wait') {
                designScore += 15;
            } else if (d.peek === 'weekly') {
                designScore += 8;
            } else {
                designScore += 0;
            }

            if (d.correction === round.bestCorrection) {
                designScore += 10;
            } else if (d.correction !== 'none') {
                designScore += 5;
            }

            if (String(d.sampleSize) === round.bestSample) {
                designScore += 12;
            } else if (d.sampleSize >= 25000) {
                designScore += 7;
            } else {
                designScore += 3;
            }

            if (String(d.duration) === round.bestDuration) {
                designScore += 8;
            } else if (d.duration >= 2) {
                designScore += 4;
            }

            if (d.metric === round.bestMetric) {
                designScore += 5;
            } else {
                designScore += 2;
            }

            if (d.decision === round.bestDecision) {
                decisionScore += 50;
            } else if (d.decision === 'followup') {
                decisionScore += 30;
            } else if (d.decision === 'noship' && round.bestDecision !== 'ship') {
                decisionScore += 25;
            } else if (d.decision === 'ship' && round.bestDecision === 'ship') {
                decisionScore += 50;
            } else {
                decisionScore += 10;
            }

            var roundScore = Math.min(designScore, maxDesign) + Math.min(decisionScore, maxDecision);
            var isCorrect = d.decision === round.bestDecision ? 1 : 0;

            var subscriberImpact = 0;
            if (roundIdx === 0) {
                subscriberImpact = d.decision === 'ship' ? 12000 : (d.decision === 'followup' ? 3000 : 0);
            } else if (roundIdx === 1) {
                subscriberImpact = d.decision === 'ship' ? -25000 : (d.decision === 'segment' ? 15000 : 0);
            } else if (roundIdx === 2) {
                subscriberImpact = d.decision === 'ship' ? -8000 : (d.decision === 'followup' ? 5000 : 0);
            } else if (roundIdx === 3) {
                subscriberImpact = d.decision === 'segment' ? 20000 : (d.decision === 'ship' ? -10000 : 2000);
            }

            state.domainState.score += roundScore;
            state.domainState.experimentsRun += 1;
            state.domainState.correctDecisions += isCorrect;
            state.domainState.subscribers += subscriberImpact;
            state.domainState.scoreHistory.push(roundScore);
            state.domainState.decisionQualityHistory.push(isCorrect ? 100 : (decisionScore >= 25 ? 50 : 0));

            // v1.1.0: expose normalized 0-100 overall (performance.overallScore) for the reporting layer.
            // domainState.score remains a 0-400 point total used by the in-sim display.
            var _rounds = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.maxPeriods) ? window.mySimulation.state.maxPeriods : this.ROUNDS.length;
            var _overall = Math.max(0, Math.min(100, Math.round(state.domainState.score / Math.max(_rounds, 1))));
            var _rating = 'Novice Experimenter';
            if (state.domainState.score >= 300 && state.domainState.correctDecisions >= 3) _rating = 'Expert Experimenter';
            else if (state.domainState.score >= 200 && state.domainState.correctDecisions >= 2) _rating = 'Proficient Experimenter';
            else if (state.domainState.score >= 120) _rating = 'Developing Experimenter';
            state.domainState.performance = { overallScore: _overall, rating: _rating, rawScore: state.domainState.score };

            state.domainState.roundDetails.push({
                roundId: round.id,
                designScore: Math.min(designScore, maxDesign),
                decisionScore: Math.min(decisionScore, maxDecision),
                totalScore: roundScore,
                correct: isCorrect
            });

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                roundName: round.id,
                designScore: Math.min(designScore, maxDesign),
                decisionScore: Math.min(decisionScore, maxDecision),
                roundScore: roundScore,
                subscriberImpact: subscriberImpact,
                correct: isCorrect,
                totalScore: state.domainState.score,
                subscribers: state.domainState.subscribers
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('scoreDisplay', 'domainState.score', (v) => v + ' pts');
            uiManager.bind('experimentsDisplay', 'domainState.experimentsRun');
            uiManager.bind('correctDisplay', 'domainState.correctDecisions');
            uiManager.bind('subscribersDisplay', 'domainState.subscribers', (v) => v.toLocaleString());
        }

        getChartConfig() {
            return {
                scoreChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Design Score',
                                data: [],
                                backgroundColor: 'rgba(52,152,219,0.7)',
                                borderColor: '#3498db',
                                borderWidth: 2
                            },
                            {
                                label: 'Decision Score',
                                data: [],
                                backgroundColor: 'rgba(46,204,113,0.7)',
                                borderColor: '#2ecc71',
                                borderWidth: 2
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: 'Score Breakdown by Round' } },
                        scales: {
                            x: { stacked: true },
                            y: { stacked: true, beginAtZero: true, max: 100 }
                        }
                    }
                },
                decisionChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Decision Quality (%)',
                            data: [],
                            borderColor: '#e74c3c',
                            backgroundColor: 'rgba(231,76,60,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.1
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: { title: { display: true, text: 'Decision Quality Over Rounds' } },
                        scales: { y: { beginAtZero: true, max: 100 } }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.scoreHistory.map(function(_, i) { return 'R' + (i + 1); });
            var designScores = state.domainState.roundDetails.map(function(r) { return r.designScore; });
            var decisionScores = state.domainState.roundDetails.map(function(r) { return r.decisionScore; });
            return {
                scoreChart: {
                    labels: labels,
                    datasets: [
                        { data: designScores },
                        { data: decisionScores }
                    ]
                },
                decisionChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.decisionQualityHistory }]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var totalScore = history.reduce(function(s, r) { return s + (r.results ? r.results.roundScore : 0); }, 0);
            var correctCount = history.reduce(function(s, r) { return s + (r.results ? r.results.correct : 0); }, 0);
            var avgScore = totalScore / history.length;

            var performance = 'Novice Experimenter';
            if (totalScore >= 300 && correctCount >= 3) {
                performance = 'Expert Experimenter';
            } else if (totalScore >= 200 && correctCount >= 2) {
                performance = 'Proficient Experimenter';
            } else if (totalScore >= 120) {
                performance = 'Developing Experimenter';
            }

            var insights = [];
            if (correctCount === 4) {
                insights.push('Perfect decision record! You demonstrated excellent evidence-based reasoning.');
            } else if (correctCount >= 2) {
                insights.push('Good decision-making. Review the rounds where your choices diverged from optimal.');
            } else {
                insights.push('Focus on interpreting statistical results more carefully before making ship decisions.');
            }
            if (avgScore >= 75) {
                insights.push('Strong experimental design skills across all rounds.');
            } else {
                insights.push('Consider the impact of sample size, peeking behavior, and multiple comparison corrections on result reliability.');
            }

            var overallScore = Math.max(0, Math.min(100, Math.round(avgScore)));
            return {
                totalScore: totalScore,
                averageScore: Math.round(avgScore),
                overallScore: overallScore,
                score: overallScore,
                correctDecisions: correctCount + ' of 4',
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.correct === 0) {
                return window.mySimulation.t('hint_wrong_decision');
            }
            if (results.designScore < 25) {
                return window.mySimulation.t('hint_weak_design');
            }
            if (results.roundScore >= 80) {
                return window.mySimulation.t('hint_great_round');
            }
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.roundName', label: 'Experiment', i18nKey: 'col_round' },
                { key: 'decisions.metric', label: 'Primary Metric', i18nKey: 'col_metric' },
                { key: 'decisions.decision', label: 'Ship Decision', i18nKey: 'col_decision' },
                { key: 'results.designScore', label: 'Design Score', i18nKey: 'col_design', formatter: (v) => v + '/50' },
                { key: 'results.decisionScore', label: 'Decision Score', i18nKey: 'col_dec_score', formatter: (v) => v + '/50' },
                { key: 'results.roundScore', label: 'Total', i18nKey: 'col_total', formatter: (v) => v + '/100' }
            ];
        }

        getPresets() { return null; }

        getTranslations() {
            return {
                en: {
                    title:              `TestLab: A/B Testing Lab`,
                    subtitle:           `StreamFlow Experimentation Team`,
                    round_label:        `Round`,
                    period_of:          `of`,
                    score_label:        `Total Score`,
                    experiments_label:  `Experiments Run`,
                    correct_label:      `Correct Decisions`,
                    subscribers_label:  `Subscribers`,
                    briefing_heading:   `Experiment Briefing`,
                    decisions_heading:  `Your Experiment Design`,
                    sample_label:       `Sample Size (per group)`,
                    duration_label:     `Test Duration`,
                    metric_label:       `Primary Metric Focus`,
                    correction_label:   `Multiple Comparison Correction`,
                    peek_label:         `Result Checking Strategy`,
                    decision_label:     `Ship Decision`,
                    results_heading:    `Experiment Results`,
                    submit_btn:         `Submit Experiment Decisions`,
                    undo_btn:           `Undo Last Round`,
                    history_heading:    `Experiment History`,
                    missing_warning:    `Please fill in all experiment design fields before submitting.`,
                    hint_wrong_decision: `Your ship decision did not match the optimal choice. Review the statistical evidence and consider effect sizes, confidence intervals, and segment-level data.`,
                    hint_weak_design:   `Your experiment design could be stronger. Consider larger sample sizes, proper multiple comparison corrections, and disciplined result checking.`,
                    hint_great_round:   `Excellent round! Your experimental rigor and decision-making were top-notch.`,
                    col_round:          `Experiment`,
                    col_metric:         `Primary Metric`,
                    col_decision:       `Ship Decision`,
                    col_design:         `Design Score`,
                    col_dec_score:      `Decision Score`,
                    col_total:          `Total`,
                    r1_title:           `Round 1: Onboarding Funnel Optimization`,
                    r1_briefing:        `<strong>Hypothesis:</strong> Showing personalized class recommendations immediately after signup will increase conversion to first class view by 25%.<br><br><strong>Context:</strong> StreamFlow onboarding is clunky. 30% of free users never view a class (drop at step 2). The product team built a recommendation engine to show personalized classes right after signup.<br><br><strong>Current baseline:</strong> 30% of free users view a class within 7 days.<br><br><strong>Your task:</strong> Design the experiment (sample size, duration, metrics, corrections) and then decide whether to ship based on the results.<br><br><strong>Results will show:</strong> Control = 30.2% (CI: 28.8%-31.6%), Treatment = 32.1% (CI: 30.7%-33.5%), p = 0.12. A directional improvement (+1.9pp) but not statistically significant at alpha = 0.05. All guardrail metrics pass.<br><br><strong>Key consideration:</strong> Low-risk change with directional evidence. Shipping cost is minimal. Is the evidence enough to act?`,
                    r1_results:         `<strong>Control:</strong> 30.2% conversion (95% CI: 28.8% - 31.6%)<br><strong>Treatment:</strong> 32.1% conversion (95% CI: 30.7% - 33.5%)<br><strong>Difference:</strong> +1.9 percentage points (+6.3% relative)<br><strong>P-value:</strong> 0.12 (not significant at alpha = 0.05)<br><strong>Guardrails:</strong> All pass (app crashes 0.3%, time-to-class 1.8 min, trial completion 32%)<br><br>Effect is directional but not statistically significant. Shipping cost is low and change is easily reversible.`,
                    r2_title:           `Round 2: Pricing Page Experiment`,
                    r2_briefing:        `<strong>Hypothesis:</strong> Raising price from 5 EUR/month to 9 EUR/month will increase net revenue per visitor.<br><br><strong>Context:</strong> StreamFlow pricing is low (5 EUR/month). Marketing believes there is room to raise prices. Research shows price elasticity exists in the 5-10 EUR range.<br><br><strong>Current baseline:</strong> 8.2% conversion to paid at 5 EUR/month.<br><br><strong>Your task:</strong> Choose between conversion rate or revenue per user as primary metric. Design the experiment carefully — multiple metrics may give contradictory signals.<br><br><strong>Results will show:</strong> Conversion drops 21% (p < 0.001) but revenue per user rises 19% (p < 0.05). Net revenue impact is -6%. Early churn data suggests higher-price customers churn faster.<br><br><strong>Key consideration:</strong> Multiple metrics give contradictory signals. Segmentation by user type may reveal different price sensitivities.`,
                    r2_results:         `<strong>Control (5 EUR/month):</strong> Conversion 8.2% (CI: 7.6%-8.8%), Avg Rev/User 4.92 EUR<br><strong>Treatment (9 EUR/month):</strong> Conversion 6.5% (CI: 5.9%-7.1%), Avg Rev/User 5.85 EUR<br><strong>Conversion difference:</strong> -1.7pp (-21% relative), p < 0.001 (highly significant)<br><strong>Revenue/user difference:</strong> +0.93 EUR (+19% relative), p < 0.05<br><strong>Net revenue impact:</strong> Revenue/user up 19%, but applied to 21% fewer conversions = -6% net<br><strong>7-day churn:</strong> Control 0.8%, Treatment 2.1%<br><br>Contradictory signals: conversion down, revenue per user up. Net effect is negative. Consider segmented pricing.`,
                    r3_title:           `Round 3: Feature Rollout — Recommendation Engine`,
                    r3_briefing:        `<strong>Hypothesis:</strong> Personalized recommendations will increase average watch time per user by 15%.<br><br><strong>Context:</strong> Engineering built an ML recommendation engine. Test group gets personalized class recommendations; control gets popular classes. Manager wants daily result checks to ship ASAP.<br><br><strong>Challenges:</strong><br>1. Peeking temptation: daily checking inflates false positive rate (~65% chance of false positive after 20 days)<br>2. Network effects: recommendation engine draws from same content pool (SUTVA violation)<br>3. Multiple metrics: watch time, class completion, churn, satisfaction, DAU<br><br><strong>Results will show:</strong> Watch time up 13% (p = 0.002) but DAU dropped slightly (p = 0.08). Other metrics not significant. The DAU drop suggests a potential bug on some devices.<br><br><strong>Key consideration:</strong> Significant primary metric result but unexpected secondary metric decline warrants investigation before full rollout.`,
                    r3_results:         `<strong>Watch time:</strong> Control 45 min/week, Treatment 51 min/week (+13%), p = 0.002 (significant)<br><strong>Class completion:</strong> Control 70%, Treatment 72%, p = 0.18 (not significant)<br><strong>Churn:</strong> Control 5.1%, Treatment 4.9%, p = 0.35 (not significant)<br><strong>Satisfaction:</strong> Control 7.2/10, Treatment 7.3/10, p = 0.42 (not significant)<br><strong>DAU:</strong> Control 35%, Treatment 33%, p = 0.08 (not significant but dropped)<br><br>Primary metric is positive and significant, but DAU decline is concerning. Possible device-specific bug causing crashes for some users. Shipping without investigation carries risk.`,
                    r4_title:           `Round 4: Retention Campaign — Win-Back`,
                    r4_briefing:        `<strong>Hypothesis:</strong> A win-back campaign (email + SMS + free trial) will re-activate 15% of churned users within 30 days.<br><br><strong>Context:</strong> StreamFlow wants to win back churned users. Treatment group gets email + SMS reminder + 1-week free trial offer; control gets nothing.<br><br><strong>Warning — Simpson Paradox:</strong> Aggregate results look positive (+4pp, p < 0.001). But segment analysis reveals the truth:<br>- Price-sensitive churners: campaign HURTS re-activation (-5pp)<br>- Life-circumstances churners: campaign HELPS massively (+16pp)<br>- Treatment group happened to have more life-circumstance churners, inflating aggregate<br><br><strong>Key consideration:</strong> Never trust aggregate results without segment analysis. The optimal approach is segment-specific campaigns with different messaging for each churn reason.`,
                    r4_results:         `<strong>Overall Aggregate:</strong><br>Control: 8% re-activated (800/10,000)<br>Treatment: 12% re-activated (1,200/10,000)<br>Difference: +4pp (+50% relative), p < 0.001<br><br><strong>SEGMENT ANALYSIS (Simpson Paradox):</strong><br><strong>Price-sensitive (5,000 each):</strong> Control 15%, Treatment 10% — campaign HURTS (-5pp)<br><strong>Life-circumstances (5,000 each):</strong> Control 2%, Treatment 18% — campaign HELPS (+16pp)<br><br>Aggregate is positive only because treatment had more life-circumstance churners (randomization imbalance). Price-sensitive users are harmed by the campaign. Segment-specific targeting is the optimal approach.`
                },
                es: {
                    title:              `TestLab: Laboratorio de Pruebas A/B`,
                    subtitle:           `Equipo de Experimentacion de StreamFlow`,
                    round_label:        `Ronda`,
                    period_of:          `de`,
                    score_label:        `Puntuacion Total`,
                    experiments_label:  `Experimentos Ejecutados`,
                    correct_label:      `Decisiones Correctas`,
                    subscribers_label:  `Suscriptores`,
                    briefing_heading:   `Informe del Experimento`,
                    decisions_heading:  `Tu Diseno Experimental`,
                    sample_label:       `Tamano de Muestra (por grupo)`,
                    duration_label:     `Duracion de la Prueba`,
                    metric_label:       `Metrica Principal`,
                    correction_label:   `Correccion por Comparaciones Multiples`,
                    peek_label:         `Estrategia de Revision de Resultados`,
                    decision_label:     `Decision de Lanzamiento`,
                    results_heading:    `Resultados del Experimento`,
                    submit_btn:         `Enviar Decisiones del Experimento`,
                    undo_btn:           `Deshacer Ultima Ronda`,
                    history_heading:    `Historial de Experimentos`,
                    missing_warning:    `Por favor completa todos los campos de diseno experimental antes de enviar.`,
                    hint_wrong_decision: `Tu decision de lanzamiento no coincide con la opcion optima. Revisa la evidencia estadistica y considera los tamanos de efecto, intervalos de confianza y datos por segmento.`,
                    hint_weak_design:   `Tu diseno experimental podria ser mas robusto. Considera tamanos de muestra mayores, correcciones por comparaciones multiples y revision disciplinada de resultados.`,
                    hint_great_round:   `Excelente ronda! Tu rigor experimental y toma de decisiones fueron sobresalientes.`,
                    col_round:          `Experimento`,
                    col_metric:         `Metrica Principal`,
                    col_decision:       `Decision`,
                    col_design:         `Diseno`,
                    col_dec_score:      `Decision`,
                    col_total:          `Total`,
                    r1_title:           `Ronda 1: Optimizacion del Embudo de Incorporacion`,
                    r1_briefing:        `<strong>Hipotesis:</strong> Mostrar recomendaciones personalizadas de clases inmediatamente despues del registro aumentara la conversion a primera vista de clase en un 25%.<br><br><strong>Contexto:</strong> El proceso de incorporacion de StreamFlow es torpe. El 30% de usuarios gratuitos nunca ve una clase. El equipo de producto construyo un motor de recomendaciones para mostrar clases personalizadas justo despues del registro.<br><br><strong>Linea base actual:</strong> 30% de usuarios gratuitos ven una clase en 7 dias.<br><br><strong>Tu tarea:</strong> Disena el experimento y decide si lanzar basandote en los resultados.<br><br><strong>Resultados:</strong> Control = 30.2%, Tratamiento = 32.1%, p = 0.12. Mejora direccional (+1.9pp) pero no estadisticamente significativa. Todas las metricas de control pasan.`,
                    r1_results:         `<strong>Control:</strong> 30.2% conversion (IC 95%: 28.8% - 31.6%)<br><strong>Tratamiento:</strong> 32.1% conversion (IC 95%: 30.7% - 33.5%)<br><strong>Diferencia:</strong> +1.9 puntos porcentuales (+6.3% relativo)<br><strong>Valor p:</strong> 0.12 (no significativo a alfa = 0.05)<br><strong>Metricas de control:</strong> Todas pasan`,
                    r2_title:           `Ronda 2: Experimento de Pagina de Precios`,
                    r2_briefing:        `<strong>Hipotesis:</strong> Subir el precio de 5 EUR/mes a 9 EUR/mes aumentara los ingresos netos por visitante.<br><br><strong>Contexto:</strong> El precio de StreamFlow es bajo (5 EUR/mes). Marketing cree que hay espacio para subir precios.<br><br><strong>Resultados:</strong> La conversion baja 21% (p < 0.001) pero los ingresos por usuario suben 19% (p < 0.05). Impacto neto en ingresos: -6%. La desercion temprana sugiere que los clientes de precio alto abandonan mas rapido.<br><br><strong>Consideracion clave:</strong> Multiples metricas dan senales contradictorias. La segmentacion por tipo de usuario puede revelar diferentes sensibilidades al precio.`,
                    r2_results:         `<strong>Control (5 EUR/mes):</strong> Conversion 8.2%, Ingreso/Usuario 4.92 EUR<br><strong>Tratamiento (9 EUR/mes):</strong> Conversion 6.5%, Ingreso/Usuario 5.85 EUR<br><strong>Diferencia conversion:</strong> -1.7pp (-21% relativo), p < 0.001<br><strong>Diferencia ingreso/usuario:</strong> +0.93 EUR (+19% relativo), p < 0.05<br><strong>Impacto neto:</strong> -6% en ingresos totales`,
                    r3_title:           `Ronda 3: Lanzamiento de Funcion — Motor de Recomendaciones`,
                    r3_briefing:        `<strong>Hipotesis:</strong> Las recomendaciones personalizadas aumentaran el tiempo de visualizacion promedio por usuario en un 15%.<br><br><strong>Contexto:</strong> El equipo de ingenieria construyo un motor de recomendaciones basado en ML. El gerente quiere revisar resultados diariamente para lanzar lo antes posible.<br><br><strong>Desafios:</strong> Tentacion de revisar resultados antes de tiempo, efectos de red y metricas multiples.<br><br><strong>Resultados:</strong> Tiempo de visualizacion sube 13% (p = 0.002) pero DAU baja ligeramente (p = 0.08). La caida de DAU sugiere un posible error en algunos dispositivos.`,
